
import numpy as np
import torch
import matplotlib.pyplot as plt

from models.mlp import ElectrodeMLP

torch.manual_seed(42)

# Load pretrained forward model
model = ElectrodeMLP()
model.load_state_dict(
    torch.load(
        "checkpoints/electrode_mlp_best.pth",
        map_location="cpu",
        weights_only=True
    )
)
model.eval()

# Freeze the network parameters
for param in model.parameters():
    param.requires_grad_(False)

# Desired deformation generated by a known
# feasible configuration in our synthetic model
reference_voltages = np.array(
    [0.6, 0.2, 0.4, 0.1, 0.3, 0.5, 0.2],
    dtype=np.float32
)

# Reconstruct the simulated physical response
adj = np.zeros((7, 7), dtype=np.float32)

for i in range(1, 7):
    adj[0, i] = adj[i, 0] = 1

for i in range(1, 7):
    j = 1 + (i % 6)
    adj[i, j] = adj[j, i] = 1

coupling = adj / adj.sum(axis=1, keepdims=True)

def physics(v):
    own = 0.7*v + 0.3*v**2 + 0.1*v**3
    neighbor = 0.12 * (v**2 @ coupling.T)
    return own + neighbor

target = torch.tensor(
    physics(reference_voltages),
    dtype=torch.float32
)

# Initialize trainable normalized voltages.
# Sigmoid ensures voltage stays between 0 and 1.
raw_voltages = torch.nn.Parameter(torch.zeros(7))

optimizer = torch.optim.Adam(
    [raw_voltages], lr=0.05
)

loss_history = []

# Optimize the input, not the network weights
for step in range(1000):
    optimizer.zero_grad()

    voltages = torch.sigmoid(raw_voltages)
    prediction = model(voltages.unsqueeze(0))[0]

    loss = torch.mean((prediction - target)**2)

    loss.backward()
    optimizer.step()

    loss_history.append(loss.item())

    if (step + 1) % 100 == 0:
        print(
            f"Step {step+1}: "
            f"Loss = {loss.item():.8f}"
        )

# Evaluate optimized voltages
with torch.no_grad():
    optimal_v = torch.sigmoid(
        raw_voltages
    ).numpy()

    mlp_result = model(
        torch.tensor(optimal_v).unsqueeze(0)
    ).numpy()[0]

actual_result = physics(optimal_v)

print("\nReference voltages:")
print(reference_voltages.round(4))

print("\nOptimized voltages:")
print(optimal_v.round(4))

print("\nTarget deformation:")
print(target.numpy().round(4))

print("\nMLP predicted deformation:")
print(mlp_result.round(4))

print("\nActual simulated deformation:")
print(actual_result.round(4))

actual_rmse = np.sqrt(
    np.mean(
        (actual_result - target.numpy())**2
    )
)

print(f"\nPhysical RMSE: {actual_rmse:.6f}")

# Plot convergence
plt.figure(figsize=(8, 4))
plt.plot(loss_history)
plt.xlabel("Optimization step")
plt.ylabel("MSE")
plt.yscale("log")
plt.title("Inverse Voltage Optimization")
plt.grid(True)
plt.tight_layout()
plt.show()

# Compare target and actual achieved deformation
x = np.arange(7)

plt.figure(figsize=(9, 4))
plt.bar(
    x - 0.2, target.numpy(),
    width=0.4, label="Target"
)
plt.bar(
    x + 0.2, actual_result,
    width=0.4, label="Achieved"
)
plt.xticks(x, [f"E{i+1}" for i in range(7)])
plt.ylabel("Deformation")
plt.title("Target vs Achieved Deformation")
plt.legend()
plt.tight_layout()
plt.show()
